<script>
(function(){const btn=document.getElementById('profileMenuBtn'),drop=document.getElementById('profileDropdown');if(btn&&drop&&!btn.dataset.uiBound){btn.dataset.uiBound='1';btn.addEventListener('click',e=>{e.stopPropagation();drop.classList.toggle('open')});}document.addEventListener('click',e=>{if(drop&&!drop.parentElement.contains(e.target))drop.classList.remove('open')});window.openProfileModal=function(id){document.querySelectorAll('#profileModalOverlay .profile-dropdown-view').forEach(v=>v.style.display=v.id===id?'block':'none');document.getElementById('profileModalOverlay').classList.add('open')};document.getElementById('profileModalCloseBtn')?.addEventListener('click',()=>document.getElementById('profileModalOverlay').classList.remove('open'));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('profileModalOverlay')?.classList.contains('open'))document.getElementById('profileModalOverlay').classList.remove('open')});document.getElementById('sidebar');(function(){const themeBtn=document.getElementById('themeToggleBtn');if(!themeBtn||themeBtn.dataset.uiBound)return;themeBtn.dataset.uiBound='1';const THEME_KEY='siberad-theme';function applyTheme(theme){if(theme==='light')document.documentElement.setAttribute('data-theme','light');else document.documentElement.removeAttribute('data-theme');themeBtn.setAttribute('aria-pressed',theme==='light'?'true':'false');}let savedTheme='dark';try{savedTheme=localStorage.getItem(THEME_KEY)||'dark';}catch(e){}applyTheme(savedTheme);themeBtn.addEventListener('click',()=>{const current=document.documentElement.getAttribute('data-theme')==='light'?'light':'dark';const next=current==='light'?'dark':'light';try{localStorage.setItem(THEME_KEY,next);}catch(e){}applyTheme(next);});})();const sidebar=document.getElementById('sidebar');const ROLE_GROUP_STATE_KEY='siberad-role-group-';function positionGroupFlyout(g){const subnav=g.querySelector('.side-subnav');const gbtn=g.querySelector('.side-nav-group-title');if(!subnav||!gbtn)return;if(window.innerWidth<=900||!sidebar?.classList.contains('collapsed')||!g.classList.contains('open')){subnav.style.top='';subnav.style.left='';return;}const r=gbtn.getBoundingClientRect();subnav.style.top=r.top+'px';subnav.style.left=(r.right+8)+'px';}window.siberadRepositionSubnavFlyouts=function(){document.querySelectorAll('.side-nav-group').forEach(positionGroupFlyout);};window.addEventListener('resize',()=>window.siberadRepositionSubnavFlyouts());function restoreRoleGroupState(){document.querySelectorAll('.side-nav-group').forEach(g=>{let saved=null;try{saved=sessionStorage.getItem(ROLE_GROUP_STATE_KEY+g.id)}catch(e){}if(saved==='closed'||sidebar?.classList.contains('collapsed'))g.classList.remove('open');else if(saved==='open')g.classList.add('open');positionGroupFlyout(g);});}window.siberadRestoreGroupState=restoreRoleGroupState;restoreRoleGroupState();document.querySelectorAll('.side-nav-group').forEach(g=>{const gbtn=g.querySelector('.side-nav-group-title');gbtn?.addEventListener('click',e=>{e.stopPropagation();const willOpen=!g.classList.contains('open');if(willOpen&&sidebar?.classList.contains('collapsed')){document.querySelectorAll('.side-nav-group.open').forEach(other=>{if(other===g)return;other.classList.remove('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+other.id,'closed')}catch(err){}positionGroupFlyout(other);});}g.classList.toggle('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+g.id,g.classList.contains('open')?'open':'closed')}catch(e){}positionGroupFlyout(g);});});document.addEventListener('click',e=>{if(!sidebar?.classList.contains('collapsed'))return;if(e.target.closest('#sideCollapseBtn'))return;document.querySelectorAll('.side-nav-group.open').forEach(g=>{if(g.contains(e.target))return;g.classList.remove('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+g.id,'closed')}catch(err){}positionGroupFlyout(g);});});document.addEventListener('keydown',e=>{if(e.key!=='Escape'||!sidebar?.classList.contains('collapsed'))return;document.querySelectorAll('.side-nav-group.open').forEach(g=>{g.classList.remove('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+g.id,'closed')}catch(err){}positionGroupFlyout(g);});});document.querySelectorAll('.side-nav-group .side-sub-link').forEach(a=>a.addEventListener('click',()=>{if(!sidebar?.classList.contains('collapsed'))return;const g=a.closest('.side-nav-group');if(!g)return;g.classList.remove('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+g.id,'closed')}catch(err){}positionGroupFlyout(g);}));const ROLE_ACTIVE_TAB_KEY='siberad-role-active-tab';function showRoleSection(id,link,skipSave){document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));const el=document.getElementById(id);if(!el)return;el.classList.add('active');document.querySelectorAll('.side-link,.side-sub-link').forEach(x=>x.classList.remove('active'));if(link)link.classList.add('active');document.querySelectorAll('.side-nav-group').forEach(g=>g.classList.remove('has-active-child'));const activeGroup=link?.closest('.side-nav-group');if(activeGroup){activeGroup.classList.add('has-active-child');if(activeGroup.id)try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+activeGroup.id,'open')}catch(e){}}document.getElementById('sidebar')?.classList.remove('open');if(!skipSave){try{sessionStorage.setItem(ROLE_ACTIVE_TAB_KEY,id)}catch(e){}}}document.querySelectorAll('.side-link[href^="#"],.side-sub-link[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href').slice(1);if(!document.getElementById(id))return;e.preventDefault();showRoleSection(id,a)}));(function(){let savedId=null;try{savedId=sessionStorage.getItem(ROLE_ACTIVE_TAB_KEY)}catch(e){}if(!savedId)return;function attempt(tries){if(!document.getElementById(savedId)){if(tries<20){setTimeout(()=>attempt(tries+1),50);}else{try{sessionStorage.removeItem(ROLE_ACTIVE_TAB_KEY)}catch(e){}}return;}const link=document.querySelector('.side-link[href="#'+savedId+'"],.side-sub-link[href="#'+savedId+'"]');showRoleSection(savedId,link,true);const group=link?.closest('.side-nav-group');if(group){group.classList.add('open');if(group.id)try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+group.id,'open')}catch(e){}positionGroupFlyout(group);}}attempt(0);})();window.siberadCharts=window.siberadCharts||[];const ctx=document.getElementById('laporanChart');if(ctx){const chartLabels=['Disetujui','Ditolak','Terlambat','Dibatalkan'];const chartColors=['#22c55e','#ef4444','#ff6b6b','#c1121f'];const laporanChart=new Chart(ctx,{type:'doughnut',data:{labels:chartLabels,datasets:[{data:[{{ $stats['disetujui'] }},{{ $stats['ditolak'] }},{{ $stats['terlambat'] }},{{ $stats['dibatalkan'] }}],backgroundColor:chartColors,borderColor:'transparent',borderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}}}});window.siberadCharts.push(laporanChart);const laporanLegendBox=document.getElementById('laporanChartLegend');if(laporanLegendBox){laporanLegendBox.innerHTML='';chartLabels.forEach((l,i)=>{const item=document.createElement('span');item.className='chart-legend-item';item.innerHTML='<span class="chart-legend-dot" style="background:'+chartColors[i]+'"></span>'+l;item.addEventListener('click',function(){laporanChart.toggleDataVisibility(i);laporanChart.update();item.classList.toggle('is-hidden',!laporanChart.getDataVisibility(i));});laporanLegendBox.appendChild(item);});}}})();
window.openReportDetail=function(button){const modal=document.getElementById('reportDetailModal');document.getElementById('detailPengirim').textContent=button.dataset.pengirim||'-';document.getElementById('detailTujuan').textContent=button.dataset.tujuan||'-';document.getElementById('detailPerihal').textContent=button.dataset.perihal||'-';document.getElementById('detailPrioritas').textContent=button.dataset.prioritas||'-';document.getElementById('detailProgres').textContent=button.dataset.progres?button.dataset.progres+'%':'-';document.getElementById('detailProgresWrap').style.display=button.dataset.progres?'block':'none';document.getElementById('detailProyek').textContent=button.dataset.proyek||'-';document.getElementById('detailTanggal').textContent=button.dataset.tanggal||'-';document.getElementById('detailDeskripsiLabel').textContent=button.dataset.deskripsiLabel||'Isi Laporan';document.getElementById('detailDeskripsi').textContent=button.dataset.deskripsi||'-';const kendala=button.dataset.kendala||'';const kendalaWrap=document.getElementById('detailKendalaWrap');if(kendala){document.getElementById('detailKendala').textContent=kendala;kendalaWrap.style.display='block'}else{kendalaWrap.style.display='none'}const wrap=document.getElementById('detailLampiranWrap');const linkBox=document.getElementById('detailLampiran');let daftarLampiran=[];try{daftarLampiran=button.dataset.lampiran?JSON.parse(button.dataset.lampiran):[]}catch(e){daftarLampiran=[]}linkBox.innerHTML='';if(daftarLampiran.length){daftarLampiran.forEach(function(x,i){const a=document.createElement('a');a.href=x.url;a.target='_blank';a.rel='noopener';a.className='lampiran-btn';a.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><path d="M14 2v6h6"></path></svg><span>'+(daftarLampiran.length>1?(x.nama||'Lihat Lampiran '+(i+1)):'Lihat Lampiran')+'<